      markup+=shape.kind==='custom'?'<path d="M'+(x-7)+' '+y+'l7-5 7 5-7 5Z" class="sl-score-custom"/>':'<ellipse cx="'+x+'" cy="'+y+'" rx="'+(shape.kind==='whole'?8:7)+'" ry="4.8" transform="rotate(-15 '+x+' '+y+')" class="sl-score-head'+(shape.hollow?' is-hollow':'')+'"/>';
